function StatCard({ icon: Icon, label, value, note, accent = "blue" }: { icon: typeof Activity; label: string; value: string; note: string; accent?: string }) {
  return <Card className="stat-card">
    <div className={`stat-icon ${accent}`}><Icon size={17} strokeWidth={1.8} /></div>
    <div className="stat-copy"><span>{label}</span><strong>{value}</strong><small>{note}</small></div>
  </Card>;
}

function Pill({ children, tone = "slate" }: { children: React.ReactNode; tone?: string }) {
  return <Badge variant="secondary" className={`pill ${tone}`}><span className="pill-dot" />{children}</Badge>;
}

type CommandItem = { key: string; label: string; icon: typeof Activity };
function CommandPalette({ items, onSelect, onClose }: { items: CommandItem[]; onSelect: (key: string) => void; onClose: () => void }) { return <div className="command-backdrop" onClick={onClose}><div className="command-palette" onClick={(event) => event.stopPropagation()}><div className="command-search"><Search size={16} /><input autoFocus placeholder="ابحث عن صفحة أو إجراء..." /></div><div className="command-list">{items.map((item) => <button key={item.key} onClick={() => onSelect(item.key)}><item.icon size={16} /><span>{item.label}</span><ArrowUpRight size={14} /></button>)}<button onClick={() => onSelect("settings")}><Settings2 size={16} /><span>الإعدادات</span><ArrowUpRight size={14} /></button></div><div className="command-hint"><kbd>Esc</kbd> للإغلاق</div></div></div>; }

function AppShell({ active, setActive, children, userName, logout }: { active: PageKey; setActive: (key: PageKey) => void; children: React.ReactNode; userName: string; logout: () => void }) {
  const { theme, toggleTheme } = useTheme();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [commandOpen, setCommandOpen] = useState(false);
  useEffect(() => { const handleKey = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(true); } if (event.key === "Escape") { setCommandOpen(false); setUserMenuOpen(false); } }; window.addEventListener("keydown", handleKey); return () => window.removeEventListener("keydown", handleKey); }, []);
  const commandItems: CommandItem[] = navGroups.flatMap((group) => group.items.map((item) => ({ key: String(item.key), label: item.label, icon: item.icon as typeof Activity })));
  return <div className="app-shell" dir="rtl">
    <aside className={`sidebar ${mobileOpen ? "mobile-open" : ""}`}>
      <div className="brand-row">
        <div className="brand-mark"><img src="/manus-storage/venture-os-mark_cc2bdbe7.png" alt="" /></div>
        <div><strong>Venture OS</strong><span>مختبرك الشخصي</span></div>
        <button className="icon-button sidebar-close" onClick={() => setMobileOpen(false)}><X size={17} /></button>
      </div>
      <nav className="side-nav">
        {navGroups.map((group) => <div className="nav-group" key={group.label}><span className="nav-label">{group.label}</span>{group.items.map((item) => <button key={item.key} className={`nav-item ${active === item.key ? "active" : ""}`} onClick={() => { setActive(item.key as PageKey); setMobileOpen(false); }}><item.icon size={17} strokeWidth={active === item.key ? 2.1 : 1.7} /><span>{item.label}</span>{item.key === "tasks" && <b className="nav-count">3</b>}</button>)}</div>)}
      </nav>
      <div className="sidebar-bottom"><div className="sidebar-status"><span className="live-dot" /><div><strong>المساعد متصل</strong><span>آخر مزامنة منذ 3 د</span></div></div></div>
    </aside>
    <main className="main-shell">
      <header className="topbar"><button className="mobile-menu icon-button" onClick={() => setMobileOpen(true)}><Menu size={19} /></button><div className="breadcrumbs"><span>Venture OS</span><span>/</span><strong>{pageMeta[active].title}</strong></div><div className="top-actions"><button className="search-trigger" onClick={() => setCommandOpen(true)}><Search size={16} /><span>ابحث وتنقل في مساحتك</span><kbd>⌘ K</kbd></button><button className="icon-button" onClick={() => toast("لا توجد تنبيهات جديدة") }><Bell size={18} /><i className="notification-dot" /></button><button className="icon-button" onClick={toggleTheme}>{theme === "dark" ? <Sun size={18} /> : <Moon size={18} />}</button><div className="user-menu-wrap"><button className="user-trigger" onClick={() => setUserMenuOpen((open) => !open)} aria-expanded={userMenuOpen}><span className="top-avatar">{userName.slice(0, 1)}</span><span className="user-trigger-name">{userName}</span><ChevronDown size={14} /></button>{userMenuOpen && <div className="user-menu"><div className="user-menu-heading"><span className="top-avatar">{userName.slice(0, 1)}</span><div><strong>{userName}</strong><small>مساحة شخصية</small></div></div><button onClick={() => { setActive("settings"); setUserMenuOpen(false); }}><Settings2 size={15} /> الإعدادات</button><button onClick={() => { setUserMenuOpen(false); logout(); }}><LogOut size={15} /> تسجيل الخروج</button></div>}</div></div></header>
      <div className="page-content">{children}</div>
    {commandOpen && <CommandPalette items={commandItems} onSelect={(key) => { setActive(key as PageKey); setCommandOpen(false); }} onClose={() => setCommandOpen(false)} />}
    </main>
  </div>;
}

function DashboardCharts() { const { isAuthenticated } = useAuth(); const githubQuery = trpc.github.status.useQuery(undefined, { enabled: isAuthenticated, retry: false }); const taskStatsQuery = trpc.aiTasks.stats.useQuery({ days: 14 }, { enabled: isAuthenticated, retry: false }); const [range, setRange] = useState("7d"); const github = githubQuery.data?.connected ? githubQuery.data : null; const progressData = github ? [{ name: github.repo.split("/").pop() ?? "GitHub", value: github.health }, ...projectProgressData.slice(0, 3)] : projectProgressData; const marketData = github ? marketSignalData.map((item, index) => index === marketSignalData.length - 1 ? { ...item, signals: Math.max(item.signals, github.recentCommits), opportunities: Math.max(item.opportunities, Math.min(github.openIssues, 9)) } : item) : marketSignalData; return <section className="charts-grid"><Card className="chart-card"><div className="panel-head"><div><p className="eyebrow">Project pulse</p><h2>تقدم المشاريع</h2><span className="chart-note">{github ? "تتضمن حالة مستودع GitHub المرتبط" : "نسبة الإنجاز الحالية لكل مشروع"}</span></div><select value={range} onChange={(e) => setRange(e.target.value)} aria-label="فترة الرسم"><option value="7d">هذا الأسبوع</option><option value="30d">هذا الشهر</option></select></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={progressData} layout="vertical" margin={{ top: 8, right: 12, left: 8, bottom: 8 }}><CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="var(--border)" /><XAxis type="number" domain={[0, 100]} tick={{ fill: "var(--muted-foreground)", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis dataKey="name" type="category" width={84} tick={{ fill: "var(--foreground)", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip cursor={{ fill: "var(--accent)" }} contentStyle={{ background: "var(--popover)", border: "1px solid var(--border)", borderRadius: 8, color: "var(--popover-foreground)", fontFamily: "Cairo" }} formatter={(value) => [`${value}%`, "الإنجاز"]} /><Bar dataKey="value" fill="var(--foreground)" radius={[0, 4, 4, 0]} barSize={14} /></BarChart></ResponsiveContainer></div></Card><Card className="chart-card"><div className="panel-head"><div><p className="eyebrow">Market signals</p><h2>إشارات السوق</h2><span className="chart-note">{github ? `محدثة من GitHub: ${github.openIssues} issues و${github.openPullRequests} PRs` : "الإشارات والفرص التي اكتشفها المسح اليومي"}</span></div><div className="chart-legend"><span><i className="legend-line solid" /> إشارات</span><span><i className="legend-line dashed" /> فرص</span></div></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><LineChart data={marketData} margin={{ top: 8, right: 8, left: -12, bottom: 4 }}><CartesianGrid strokeDasharray="3 3" stroke="var(--border)" /><XAxis dataKey="day" tick={{ fill: "var(--muted-foreground)", fontSize: 9 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "var(--muted-foreground)", fontSize: 9 }} axisLine={false} tickLine={false} width={24} /><Tooltip contentStyle={{ background: "var(--popover)", border: "1px solid var(--border)", borderRadius: 8, color: "var(--popover-foreground)", fontFamily: "Cairo" }} /><Line type="monotone" dataKey="signals" stroke="var(--foreground)" strokeWidth={2} dot={{ r: 3, fill: "var(--foreground)" }} activeDot={{ r: 5 }} name="إشارات" /><Line type="monotone" dataKey="opportunities" stroke="var(--muted-foreground)" strokeWidth={2} strokeDasharray="5 5" dot={{ r: 3, fill: "var(--background)", stroke: "var(--foreground)" }} name="فرص" /></LineChart></ResponsiveContainer></div></Card><Card className="chart-card"><div className="panel-head"><div><p className="eyebrow">AI execution</p><h2>نجاح وفشل المهام</h2><span className="chart-note">آخر 14 يومًا من سجل التشغيل الفعلي</span></div><div className="chart-legend"><span><i className="legend-line solid" /> نجاح</span><span><i className="legend-line dashed" /> فشل</span></div></div><div className="chart-wrap">{taskStatsQuery.isLoading ? <div className="chart-empty-state"><Loader2 size={24} className="spin" /><span>جارٍ تحميل إحصائيات المهام...</span></div> : taskStatsQuery.isError ? <div className="chart-empty-state"><AlertTriangle size={24} /><span>تعذر تحميل الإحصائيات حاليًا</span><button className="outline-button small" onClick={() => taskStatsQuery.refetch()}>إعادة المحاولة</button></div> : (taskStatsQuery.data?.length ?? 0) === 0 ? <div className="chart-empty-state"><Activity size={24} /><span>ستظهر الإحصائيات بعد أول تشغيل لمهمة AI</span></div> : <ResponsiveContainer width="100%" height="100%"><LineChart data={taskStatsQuery.data} margin={{ top: 8, right: 8, left: -12, bottom: 4 }}><CartesianGrid strokeDasharray="3 3" stroke="var(--border)" /><XAxis dataKey="date" tick={{ fill: "var(--muted-foreground)", fontSize: 9 }} tickFormatter={(value) => String(value).slice(5)} axisLine={false} tickLine={false} /><YAxis allowDecimals={false} tick={{ fill: "var(--muted-foreground)", fontSize: 9 }} axisLine={false} tickLine={false} width={24} /><Tooltip contentStyle={{ background: "var(--popover)", border: "1px solid var(--border)", borderRadius: 8, color: "var(--popover-foreground)", fontFamily: "Cairo" }} /><Line type="monotone" dataKey="success" stroke="var(--foreground)" strokeWidth={2} dot={{ r: 3, fill: "var(--foreground)" }} name="نجاح" /><Line type="monotone" dataKey="failed" stroke="var(--muted-foreground)" strokeWidth={2} strokeDasharray="5 5" dot={{ r: 3, fill: "var(--background)", stroke: "var(--foreground)" }} name="فشل" /></LineChart></ResponsiveContainer>}</div></Card></section>; }

